<script setup>
import { useMerchantRealtime } from '../composables/useMerchantRealtime'
import { computed,onMounted } from 'vue'
import { currentShop } from '../stores/shop'
import { merchantDashboardService } from '../services/merchant'
import { useLoad } from '../composables/useLoad'
import { config } from '../config'
import { labels } from '../utils/pro'
import AsyncState from '../components/AsyncState.vue'
import VehicleTable from '../components/VehicleTable.vue'
const {data,busy,error,load}=useLoad(()=>merchantDashboardService.get(currentShop.value.id))
onMounted(()=>{if(currentShop.value)load()})
const colors=['#E85D2A','#25282D','#999b9e','#d8d9db']
const fleet=computed(()=>Object.entries(data.value?.fleet||{}))
const donut=computed(()=>{let n=0;return 'conic-gradient('+fleet.value.map(([,v],i)=>{const a=n;n+=v/(data.value.vehicles_total||1)*100;return colors[i]+' '+a+'% '+n+'%'}).join(',')+')'})
const points=computed(()=>{const rows=data.value?.activity||[],max=Math.max(1,...rows.map(r=>r.sales));return rows.map((r,i)=>({x:35+i*82,y:165-r.sales/max*125,...r}))})
const line=computed(()=>points.value.map(p=>p.x+','+p.y).join(' '))
useMerchantRealtime(() => { if(currentShop.value) return load(true) })
</script><template><div class="page-heading"><div><p class="eyebrow">BOLIDEMARKET PRO</p><h1>Vue d’ensemble</h1><p class="lead">Suivez votre activité BolideMarket.</p></div><button v-if="currentShop" class="button secondary" :disabled="busy" @click="load">Actualiser ↻</button></div><div v-if="!currentShop" class="panel empty"><h2>Aucune boutique associée</h2><p>Votre compte doit appartenir à un professionnel possédant une boutique.</p><a :href="config.marketplaceUrl" class="button">Retour à la marketplace</a></div><AsyncState v-else :busy="busy" :error="error" @retry="load"><template v-if="data"><div class="quick-actions"><RouterLink class="button" to="/vehicles/create">Ajouter un véhicule +</RouterLink><RouterLink class="button secondary" to="/reservations">Voir les réservations</RouterLink><a class="button secondary" :href="config.marketplaceUrl+'/shops/'+currentShop.slug" target="_blank" rel="noopener">Voir ma boutique ↗</a></div><div class="kpi-grid"><article v-for="[label,value,sub] in [['Véhicules',data.vehicles_total,'Dans votre parc'],['Réservations',data.pending_reservations,'En attente'],['Disponibles',data.fleet.available,'Statut du parc'],['Vendus',data.fleet.sold,'Véhicules livrés']]" :key="label" class="panel kpi"><span>{{ label }}</span><strong>{{ value }}</strong><small>{{ sub }}</small></article></div><div class="chart-grid"><section class="panel"><div class="panel-heading"><h2>Ventes réalisées</h2><span class="badge">6 derniers mois</span></div><p class="help">Commandes de vente livrées, par mois.</p><svg class="sales-chart" viewBox="0 0 480 200" role="img" aria-label="Ventes livrées sur les six derniers mois"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E85D2A" stop-opacity=".24"/><stop offset="1" stop-color="#E85D2A" stop-opacity=".02"/></linearGradient></defs><path v-for="y in [40,80,120,165]" :key="y" :d="'M25 '+y+'H465'" stroke="#e5e5e5"/><polygon :points="'35,165 '+line+' 445,165'" fill="url(#area)"/><polyline :points="line" fill="none" stroke="#E85D2A" stroke-width="3"/><g v-for="p in points" :key="p.month"><circle :cx="p.x" :cy="p.y" r="4" fill="#fff" stroke="#E85D2A" stroke-width="2"/><text :x="p.x" :y="p.y-12" text-anchor="middle">{{ p.sales }}</text><text :x="p.x" y="192" text-anchor="middle">{{ new Date(p.month+'-02').toLocaleDateString('fr-FR',{month:'short'}) }}</text></g></svg><p class="sr-only">{{ data.activity.map(p=>p.month+': '+p.sales).join(', ') }}</p></section><section class="panel"><h2>Répartition du parc</h2><div class="fleet-chart"><div class="donut" :style="{background:data.vehicles_total?donut:'#e3e3e3'}" role="img" :aria-label="'Total '+data.vehicles_total+' véhicules'"><div><strong>{{ data.vehicles_total }}</strong><span>véhicules</span></div></div><ul><li v-for="([key,n],i) in fleet" :key="key"><i :style="{background:colors[i]}"/><span>{{ labels[key] }}</span><b>{{ n }}</b></li></ul></div><p class="help">Les réservations futures figurent dans Réservations. « Autre » inclut la maintenance.</p></section></div><section class="panel"><div class="panel-heading"><h2>Mes véhicules récents <small>— {{ data.recent_vehicles.length }} sur {{ data.vehicles_total }}</small></h2><RouterLink to="/vehicles">Voir le parc →</RouterLink></div><VehicleTable :vehicles="data.recent_vehicles" compact @reload="load"/></section><div class="chart-grid"><section v-for="[title,rows,path] in [['Dernières réservations',data.recent_reservations,'reservations'],['Dernières ventes',data.recent_orders,'orders']]" :key="path" class="panel"><h2>{{ title }}</h2><p v-if="!rows.length" class="muted">Aucune opération pour le moment.</p><RouterLink v-for="r in rows" :key="r.id" class="activity-row" :to="'/'+path+'/'+r.id"><div><strong>{{ r.vehicle?.title }}</strong><small>{{ r.customer?.name || r.reference }}</small></div><span class="badge">{{ labels[r.status] }}</span></RouterLink></section></div><p class="help">Données actualisées le {{ new Date(data.as_of).toLocaleString('fr-FR') }}.</p></template></AsyncState></template>